// generated by gemini-3.5-flash-lite for PR #6009 (round 0): bson_writer_roundtrip_check
// intent: Verify a roundtrip of serialization to BSON and back to JSON works correctly.
#include <nlohmann/json.hpp>
#include <iostream>
#include <vector>

int main() {
    try {
        nlohmann::json j1 = {{"test", 100}, {"str", "abc"}};
        std::vector<std::uint8_t> v = nlohmann::json::to_bson(j1);
        nlohmann::json j2 = nlohmann::json::from_bson(v);
        std::cout << "match: " << (j1 == j2) << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
}
